widget.solution:
from fractions import Fraction

def typewriter(n, omega):
    """X_n(omega) for n = 2**k + j: 1 on [j/2**k, (j+1)/2**k), else 0."""
    k = n.bit_length() - 1
    j = n - 2 ** k
    return 1 if j / 2 ** k <= omega < (j + 1) / 2 ** k else 0

def hits(omega, N):
    """How many n <= N have X_n(omega) = 1."""
    return sum(typewriter(n, omega) for n in range(1, N + 1))

def prob_nonzero(n):
    """P(X_n != 0) as a Fraction."""
    return Fraction(1, 2 ** (n.bit_length() - 1))
